CREATE OR REPLACE FUNCTION public.normalize_financial_group_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.person_id='00000000-0000-0000-0000-000000000000' THEN new.person_id:=NULL; END IF; IF new.work_id='00000000-0000-0000-0000-000000000000' THEN IF new.direction='entrada' THEN RAISE EXCEPTION 'Selecione a obra do recebimento.'; END IF; new.work_id:=NULL; END IF; RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.normalize_company_group() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF new.work_id='00000000-0000-0000-0000-000000000000' THEN IF new.source<>'manual' THEN RAISE EXCEPTION 'Selecione uma obra.'; END IF; new.work_id:=NULL; END IF; RETURN new; END $$; CREATE TRIGGER aaa_company_group BEFORE INSERT ON public.financial_groups FOR EACH ROW EXECUTE FUNCTION public.normalize_company_group();